      targetWords: ["slave", "royal", "frustrated", "stupid", "struggle", "authority", "division", "govern", "disorder", "destruction", "aid", "capital", "attempted", "defended", "relieve", "cooperated", "enabled", "plenty", "reputation", "admire"],
      readingComprehension: [
        { id: "rc_9_1", question: "What is this story about?", options: ["How a slave became a king", "How a stupid mistake made Bartelby a slave", "How a lad found plenty of food", "How a man aided poor people"], answer: "How a man aided poor people" },
        { id: "rc_9_2", question: "What did Bartelby do in the capital?", options: ["He cooperated with his group of friends.", "He enabled Gilliam to have authority over the king.", "He relieved Gilliam of his hunger.", "He found a mask to wear."], answer: "He relieved Gilliam of his hunger." },
        { id: "rc_9_3", question: "In paragraph 1, we can infer that", options: ["Bartelby did not like the royal family", "the family attempted to cause disorder", "the other children were not clever", "Bartelby had a bad reputation"], answer: "Bartelby did not like the royal family" },
        { id: "rc_9_4", question: "According to the passage, all the following are true EXCEPT", options: ["people today still admire Bartleby", "Gilliam struggled with Bartley", "Bartleby defended Gilliam", "the fighting caused destruction"], answer: "Gilliam struggled with Bartley" },
        { id: "rc_9_5", question: "What frustrated Bartelby when he was a child?", options: ["Seeing other children play while he always had to work.", "Having no shoes.", "Being cold in winter.", "Having to cook for the king."], answer: "Seeing other children play while he always had to work." }
      ]
